package provisioning

import (
	"strings"

	"github.com/BeppeTemp/cartographer/internal/provisioning/contract"
)

// PendingApproval reports whether sync would report a as needs_approval: a KB
// artifact that waits for the client's hash-bound approval (ArtifactRequiresApproval)
// and has none for its current content. A reserved hook is generated by the
// client and never asks.
func PendingApproval(a contract.Artifact, opts ApplyOptions) bool {
	if a.BuiltIn || a.Kind == "instructions" || contract.IsReservedHook(a.Kind, a.Name) {
		return false
	}
	return ArtifactRequiresApproval(a, opts) && !artifactAuthorized(a, opts)
}

// ApprovalReason says in a few words why a needs an approval, for a listing.
func ApprovalReason(a contract.Artifact, files []contract.ArtifactFile) string {
	switch a.Kind {
	case "mcp":
		return "MCP server descriptor"
	case "hook":
		return "hook"
	}
	for _, f := range files {
		if f.Executable {
			return "ships an executable file"
		}
	}
	return "declares hooks or MCP servers"
}

// InstalledBeforeApprovals reports whether a pre-D1141 client already installed
// a as the KB serves it now (D1166): a hook, skill or agent that needs approval,
// has no approval recorded under any hash (a stale one is a decision, not an
// absence), and whose lock entries all carry the content hash and the source of
// a. An MCP descriptor was always approval-gated, so it never qualifies. Only
// the lock decides: the file on disk is not read, and any later change to the
// artifact asks as usual.
func InstalledBeforeApprovals(a contract.Artifact, lock Lock, opts ApplyOptions) bool {
	// Only a KB artifact had a pre-D1141 install to grandfather: a plugin
	// artifact that merely sits in the lockfile must never be approved by it.
	if !strings.HasPrefix(a.Source, "kb:") || a.Kind == "mcp" || a.ContentHash == "" || !PendingApproval(a, opts) {
		return false
	}
	if _, recorded := opts.ApprovedMCP[a.Source+"\x00"+ApprovalName(a)]; recorded {
		return false
	}
	found := false
	for _, mf := range lock.Managed {
		if mf.Kind != a.Kind || mf.Name != a.Name {
			continue
		}
		if mf.ContentHash != a.ContentHash || !strings.EqualFold(mf.Source, a.Source) {
			return false
		}
		found = true
	}
	return found
}
